#!/usr/bin/env sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# Generated by build.py from recipe.yml for recipe http-listen-on-a-unix-socket. Do not edit.
set -e
cd "$(dirname "$0")"
mkdir -p site
printf '%s\n' 'hello over a socket' > site/hello.txt
printf '%s\n' 'not a socket' > taken.sock
cat > on-a-socket.sh <<'EOF'
#!/bin/sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# Serves site/ on the Unix socket file <socket>, waits until surl listens, runs <command>
# with SURL_PID set to surl's process ID, then stops surl. Exits with the command's exit code.
# Usage: sh on-a-socket.sh <socket> <listen URL> <command> [<argument>...]
socket=$1; url=$2; shift 2
surl --directory site --unix-socket "$socket" "$url" > surl.out &
SURL_PID=$!
export SURL_PID

# surl writes "Listening on" once the socket file is bound. If it exits first, it refused
# to start: pass its exit code on.
tries=0
until grep -q '^Listening on ' surl.out 2>/dev/null; do
  if ! kill -0 "$SURL_PID" 2>/dev/null; then wait "$SURL_PID"; exit; fi
  tries=$((tries + 1))
  if [ "$tries" -ge 300 ]; then echo "surl wrote no Listening on line" >&2; exit 1; fi
  sleep 0.1
done
cat surl.out

"$@"
status=$?
kill "$SURL_PID" 2>/dev/null
wait "$SURL_PID"
exit "$status"
EOF
cat > kill-it.sh <<'EOF'
#!/bin/sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# Stands in for a crash: kills the surl that on-a-socket.sh started, outright, and waits
# until it is gone.
kill -9 "$SURL_PID"
while kill -0 "$SURL_PID" 2>/dev/null; do sleep 0.1; done
EOF
sh on-a-socket.sh surl.sock http://localhost:8080/ curl -s --unix-socket surl.sock http://localhost:8080/hello.txt
